// Extract / re-inject the module source inside the webpack bundle public/c2w/dist/runcontainer.js.
//
//   node tools/c2w-bundle-source.mjs extract <bundle.js> <out.src.js>
//   node tools/c2w-bundle-source.mjs inject  <bundle.js> <in.src.js>
//
// NOT part of the normal recipe. The streaming fix in that bundle lives in its real upstream source,
// work/c2w-src/extras/runcontainerjs/src/web/runcontainer.js, is kept as
// patches/c2w-runcontainer-stream.patch (regenerated by tools/export-patches.sh, applied by
// tools/bootstrap.sh) and is produced by the normal build -- vm-build/build.sh runs `npx webpack` in
// extras/runcontainerjs and copies dist/*.js into public/c2w/dist/. Verified: pristine source + that
// patch + webpack reproduces the shipped bundle BYTE-IDENTICALLY.
//
// This exists only as an escape hatch for the case where you have a prebuilt bundle and no c2w
// checkout to rebuild from, and need to read or hot-patch what is actually being served. The bundle
// keeps each module's source as a JS string literal inside eval() on one line, which is why editing
// it by hand is error-prone; the round-trip here is byte-lossless (extract then inject reproduces the
// input exactly). Anything injected this way is LOST on the next c2w rebuild -- fix the source instead.
import { readFileSync, writeFileSync } from "node:fs";
const [mode, bundle, srcfile] = process.argv.slice(2);
const lines = readFileSync(bundle, "utf8").split("\n");
const i = lines.findIndex((l) => l.startsWith("eval(") && l.includes("runcontainer.js"));
if (i < 0) throw new Error("runcontainer module line not found");
const line = lines[i];
const open = "eval(", close = ");";
if (!line.endsWith(close)) throw new Error("unexpected module line tail");
const lit = line.slice(open.length, line.length - close.length);
if (mode === "extract") { writeFileSync(srcfile, JSON.parse(lit)); console.log(`extracted ${JSON.parse(lit).length} chars`); }
else if (mode === "inject") {
  lines[i] = open + JSON.stringify(readFileSync(srcfile, "utf8")) + close;
  writeFileSync(bundle, lines.join("\n")); console.log("injected");
} else throw new Error("mode must be extract|inject");
